-- MySQL Workbench trae activado el modo de actualizacion segura: rechaza (error 1175) los UPDATE cuyo
-- WHERE no usa una clave, como el de monto_reembolsado del final, y detiene el script ahi.
SET SQL_SAFE_UPDATES = 0;
USE DB_Cine;

