-- pelicula: trailer_url = busqueda del trailer en YouTube; poster_url = imagen en resources/ucsur/pe/posters (46 filas)
INSERT INTO pelicula (id_pelicula, titulo, sinopsis, duracion_min, clasificacion_edad, trailer_url, poster_url, fecha_estreno, estado) VALUES
(1, 'Spider-Man: Un Nuevo Día', 'Peter Parker intenta empezar de cero mientras una nueva amenaza pone a prueba su doble vida en Nueva York.', 145, '+14', 'https://www.youtube.com/results?search_query=Spider-Man%3A+Un+Nuevo+D%C3%ADa+trailer+oficial', 'posters/spider-man-un-nuevo-dia.jpg', '2026-07-31', 'EN_CARTELERA'),
(2, 'Hechizo de Amor 2', 'Las hermanas Owens regresan para proteger a una nueva generación de brujas de una antigua maldición familiar.', 115, '+14', 'https://www.youtube.com/results?search_query=Hechizo+de+Amor+2+trailer+oficial', 'posters/hechizo-de-amor-2.jpg', '2026-09-11', 'EN_CARTELERA'),
(3, 'El Levantamiento', 'Drama histórico sobre una revuelta popular que cambió el destino de toda una comunidad.', 135, '+14', 'https://www.youtube.com/results?search_query=El+Levantamiento+trailer+oficial', 'posters/el-levantamiento.jpg', '2026-09-11', 'EN_CARTELERA'),
(4, 'Fall 2: Punto Muerto', 'Dos escaladoras quedan atrapadas en lo alto de una estructura aislada y deben sobrevivir sin ayuda.', 100, '+14', 'https://www.youtube.com/results?search_query=Fall+2%3A+Punto+Muerto+trailer+oficial', 'posters/fall-2-punto-muerto.jpg', '2026-09-04', 'EN_CARTELERA'),
(5, 'Onslaught', 'Un grupo de sobrevivientes enfrenta una invasión implacable en una ciudad incomunicada.', 105, '+18', 'https://www.youtube.com/results?search_query=Onslaught+trailer+oficial', 'posters/onslaught.jpg', '2026-09-04', 'EN_CARTELERA'),
(6, 'Por Cualquier Medio', 'Un exagente decide hacer justicia por su cuenta tras el secuestro de su familia.', 110, '+14', 'https://www.youtube.com/results?search_query=Por+Cualquier+Medio+trailer+oficial', 'posters/por-cualquier-medio.jpg', '2026-09-04', 'EN_CARTELERA'),
(7, 'Resident Evil', 'Un nuevo grupo de personajes queda atrapado en las afueras de Raccoon City durante el brote del virus.', 110, '+18', 'https://www.youtube.com/results?search_query=Resident+Evil+trailer+oficial', 'posters/resident-evil.jpg', '2026-09-18', 'EN_CARTELERA'),
(8, 'Shaun el Cordero: La Bestia de Mossy Bottom', 'Shaun y el rebaño investigan a una misteriosa criatura que tiene asustada a toda la granja.', 90, 'APT', 'https://www.youtube.com/results?search_query=Shaun+el+Cordero%3A+La+Bestia+de+Mossy+Bottom+trailer+oficial', 'posters/shaun-el-cordero-la-bestia-de-mossy-bottom.jpg', '2026-09-25', 'EN_CARTELERA'),
(9, 'Primetime', 'Un intento de robo durante una transmisión en vivo se sale de control frente a millones de espectadores.', 100, '+14', 'https://www.youtube.com/results?search_query=Primetime+trailer+oficial', 'posters/primetime.jpg', '2026-09-25', 'EN_CARTELERA'),
(10, 'Verity', 'Una escritora acepta terminar los libros de una autora famosa y encuentra un manuscrito perturbador.', 115, '+14', 'https://www.youtube.com/results?search_query=Verity+trailer+oficial', 'posters/verity.jpg', '2026-10-02', 'EN_CARTELERA'),
(11, 'Other Mommy', 'Un niño empieza a sospechar que la mujer que vive en su casa no es realmente su madre.', 100, '+14', 'https://www.youtube.com/results?search_query=Other+Mommy+trailer+oficial', 'posters/other-mommy.jpg', '2026-10-09', 'EN_CARTELERA'),
(12, 'Los Inocentes', 'Un grupo de jóvenes limeños recorre la ciudad en una historia sobre la juventud y la marginalidad, basada en la obra de Oswaldo Reynoso.', 105, '+14', 'https://www.youtube.com/results?search_query=Los+Inocentes+trailer+oficial', 'posters/los-inocentes.jpg', '2026-10-15', 'EN_CARTELERA'),
(13, 'El Heladero: Dulce Sabor a Muerte', 'Un heladero ambulante esconde un secreto sangriento en un tranquilo barrio limeño.', 95, '+18', 'https://www.youtube.com/results?search_query=El+Heladero%3A+Dulce+Sabor+a+Muerte+trailer+oficial', 'posters/el-heladero-dulce-sabor-a-muerte.jpg', '2026-10-22', 'EN_CARTELERA'),
(14, 'Clayface', 'Un actor desfigurado se convierte en una criatura capaz de cambiar de forma y busca venganza en Gotham.', 115, '+14', 'https://www.youtube.com/results?search_query=Clayface+trailer+oficial', 'posters/clayface.jpg', '2026-10-23', 'EN_CARTELERA'),
(15, 'Godzilla Minus Zero', 'Japón vuelve a enfrentarse a Godzilla en una nueva lucha por sobrevivir.', 125, '+14', 'https://www.youtube.com/results?search_query=Godzilla+Minus+Zero+trailer+oficial', 'posters/godzilla-minus-zero.jpg', '2026-11-05', 'EN_CARTELERA'),
(16, 'La Casa de las Galletas', 'Thriller psicológico sobre una familia cuyo negocio de galletas esconde un oscuro pasado.', 100, '+14', 'https://www.youtube.com/results?search_query=La+Casa+de+las+Galletas+trailer+oficial', 'posters/la-casa-de-las-galletas.jpg', '2026-11-05', 'EN_CARTELERA'),
(17, 'El Club de la Seducción', 'Un grupo de amigos se inscribe en un curso para conquistar y termina aprendiendo otras lecciones.', 95, '+14', 'https://www.youtube.com/results?search_query=El+Club+de+la+Seducci%C3%B3n+trailer+oficial', 'posters/el-club-de-la-seduccion.jpg', '2026-11-05', 'EN_CARTELERA'),
(18, 'La Gran Sangre: Ojo x Ojo', 'Dragón, Tony Blades y Mandril vuelven a unirse para enfrentar una nueva amenaza en Lima.', 110, '+14', 'https://www.youtube.com/results?search_query=La+Gran+Sangre%3A+Ojo+x+Ojo+trailer+oficial', 'posters/la-gran-sangre-ojo-x-ojo.jpg', '2026-11-12', 'EN_CARTELERA'),
(19, 'Unos Ratoncitos en Apuros', 'Una familia de ratones emprende una gran aventura para salvar su hogar.', 90, 'APT', 'https://www.youtube.com/results?search_query=Unos+Ratoncitos+en+Apuros+trailer+oficial', 'posters/unos-ratoncitos-en-apuros.jpg', '2026-11-19', 'PREESTRENO'),
(20, 'Coquito: La Película', 'El libro con el que aprendieron a leer generaciones de peruanos cobra vida en una aventura familiar.', 90, 'APT', 'https://www.youtube.com/results?search_query=Coquito%3A+La+Pel%C3%ADcula+trailer+oficial', 'posters/coquito-la-pelicula.jpg', '2026-11-26', 'PREESTRENO'),
(21, 'Los Juegos del Hambre: Amanecer en la Cosecha', 'Durante el segundo Vasallaje de los 25, un joven Haymitch Abernathy lucha por sobrevivir en la arena.', 140, '+14', 'https://www.youtube.com/results?search_query=Los+Juegos+del+Hambre%3A+Amanecer+en+la+Cosecha+trailer+oficial', 'posters/los-juegos-del-hambre-amanecer-en-la-cosecha.jpg', '2026-11-19', 'PREESTRENO'),
(22, 'Yo Soy Rocky', 'La historia detrás de Rocky y de un actor desconocido que luchó por filmar su propia película.', 115, '+14', 'https://www.youtube.com/results?search_query=Yo+Soy+Rocky+trailer+oficial', 'posters/yo-soy-rocky.jpg', '2026-11-19', 'PREESTRENO'),
(23, 'Hechizo: Bienvenidos a Hexe', 'Una adolescente descubre que su familia pertenece a un mundo secreto de brujas.', 100, 'APT', 'https://www.youtube.com/results?search_query=Hechizo%3A+Bienvenidos+a+Hexe+trailer+oficial', 'posters/hechizo-bienvenidos-a-hexe.jpg', '2026-11-26', 'PREESTRENO'),
(24, 'Avengers: Doomsday', 'Los Vengadores y otros héroes deben unirse ante la llegada de Doctor Doom.', 180, '+14', 'https://www.youtube.com/results?search_query=Avengers%3A+Doomsday+trailer+oficial', 'posters/avengers-doomsday.jpg', '2026-12-17', 'PREESTRENO'),
(25, 'Rocky', 'Un boxeador de barrio recibe la oportunidad inesperada de pelear por el título mundial.', 120, '+14', 'https://www.youtube.com/results?search_query=Rocky+trailer+oficial', 'posters/rocky.jpg', '1976-11-21', 'REESTRENO'),
(26, 'Akira', 'En un Neo-Tokio postapocalíptico, un joven pandillero desarrolla poderes que amenazan a toda la ciudad.', 124, '+14', 'https://www.youtube.com/results?search_query=Akira+trailer+oficial', 'posters/akira.jpg', '1988-07-16', 'REESTRENO'),
(27, 'La Princesa Mononoke', 'Un joven guerrero queda atrapado en la guerra entre los dioses del bosque y los humanos.', 134, '+14', 'https://www.youtube.com/results?search_query=La+Princesa+Mononoke+trailer+oficial', 'posters/la-princesa-mononoke.jpg', '1997-07-12', 'REESTRENO'),
(28, 'Una Mente Brillante', 'La vida del matemático John Nash, entre su genialidad y su lucha contra la esquizofrenia.', 135, '+14', 'https://www.youtube.com/results?search_query=Una+Mente+Brillante+trailer+oficial', 'posters/una-mente-brillante.jpg', '2001-12-21', 'REESTRENO'),
(29, 'Avengers: Endgame', 'Tras el chasquido de Thanos, los Vengadores sobrevivientes intentan revertir la tragedia.', 181, '+14', 'https://www.youtube.com/results?search_query=Avengers%3A+Endgame+trailer+oficial', 'posters/avengers-endgame.jpg', '2019-04-25', 'REESTRENO'),
(30, 'La Nueva Focker', 'Greg Focker vuelve a enfrentarse a su suegro, ahora con un nuevo integrante en la familia.', 105, '+14', 'https://www.youtube.com/results?search_query=La+Nueva+Focker+trailer+oficial', 'posters/la-nueva-focker.jpg', '2026-11-26', 'PROXIMAMENTE'),
(31, 'Noche de Paz 2', 'Santa Claus vuelve a enfrentarse a un grupo de criminales en plena Navidad.', 110, '+18', 'https://www.youtube.com/results?search_query=Noche+de+Paz+2+trailer+oficial', 'posters/noche-de-paz-2.jpg', '2026-12-04', 'PROXIMAMENTE'),
(32, 'Dune: Parte Tres', 'Paul Atreides enfrenta las consecuencias de su ascenso como emperador.', 165, '+14', 'https://www.youtube.com/results?search_query=Dune%3A+Parte+Tres+trailer+oficial', 'posters/dune-parte-tres.jpg', '2026-12-18', 'PROXIMAMENTE'),
(33, 'Angry Birds 3', 'Los pájaros y los cerdos vuelven a unirse ante una nueva amenaza en Isla Pájaro.', 95, 'APT', 'https://www.youtube.com/results?search_query=Angry+Birds+3+trailer+oficial', 'posters/angry-birds-3.jpg', '2026-12-23', 'PROXIMAMENTE'),
(34, 'Jumanji: Mundo Abierto', 'Los jugadores regresan a Jumanji, convertido ahora en un mundo abierto lleno de peligros.', 120, 'APT', 'https://www.youtube.com/results?search_query=Jumanji%3A+Mundo+Abierto+trailer+oficial', 'posters/jumanji-mundo-abierto.jpg', '2026-12-25', 'PROXIMAMENTE'),
(35, 'Narnia: El Sobrino del Mago', 'Dos niños descubren unos anillos mágicos que los llevan al nacimiento de Narnia.', 130, 'APT', 'https://www.youtube.com/results?search_query=Narnia%3A+El+Sobrino+del+Mago+trailer+oficial', 'posters/narnia-el-sobrino-del-mago.jpg', '2027-02-12', 'PROXIMAMENTE'),
(36, 'Godzilla x Kong: Supernova', 'Godzilla y Kong enfrentan una nueva amenaza que pone en riesgo a toda la Tierra.', 120, '+14', 'https://www.youtube.com/results?search_query=Godzilla+x+Kong%3A+Supernova+trailer+oficial', 'posters/godzilla-x-kong-supernova.jpg', '2027-03-26', 'PROXIMAMENTE'),
(37, 'Shrek 5', 'Shrek vuelve a la aventura junto a Burro, Fiona y una nueva generación.', 95, 'APT', 'https://www.youtube.com/results?search_query=Shrek+5+trailer+oficial', 'posters/shrek-5.jpg', '2027-06-30', 'PROXIMAMENTE'),
(38, 'Spider-Man: Más Allá del Spider-Verso', 'Miles Morales continúa su viaje por el multiverso.', 140, 'APT', 'https://www.youtube.com/results?search_query=Spider-Man%3A+M%C3%A1s+All%C3%A1+del+Spider-Verso+trailer+oficial', 'posters/spider-man-mas-alla-del-spider-verso.jpg', '2027-06-04', 'PROXIMAMENTE'),
(39, 'Frozen III', 'Anna y Elsa emprenden un nuevo viaje lejos de Arendelle.', 105, 'APT', 'https://www.youtube.com/results?search_query=Frozen+III+trailer+oficial', 'posters/frozen-iii.jpg', '2027-11-24', 'PROXIMAMENTE'),
(40, 'Avengers: Secret Wars', 'El multiverso colapsa y los héroes de distintas realidades libran su batalla final.', 180, '+14', 'https://www.youtube.com/results?search_query=Avengers%3A+Secret+Wars+trailer+oficial', 'posters/avengers-secret-wars.jpg', '2027-12-17', 'PROXIMAMENTE'),
(41, 'Super Mario Galaxy: La Película', 'Mario y Luigi viajan al espacio en una nueva aventura entre galaxias.', 100, 'APT', 'https://www.youtube.com/results?search_query=Super+Mario+Galaxy%3A+La+Pel%C3%ADcula+trailer+oficial', 'posters/super-mario-galaxy-la-pelicula.jpg', '2026-04-02', 'FUERA_DE_CARTELERA'),
(42, 'Proyecto Fin del Mundo', 'Un profesor despierta solo en una nave espacial con la misión de salvar a la humanidad.', 155, '+14', 'https://www.youtube.com/results?search_query=Proyecto+Fin+del+Mundo+trailer+oficial', 'posters/proyecto-fin-del-mundo.jpg', '2026-03-20', 'FUERA_DE_CARTELERA'),
(43, 'Michael', 'La vida y carrera de Michael Jackson, desde los Jackson 5 hasta convertirse en el Rey del Pop.', 125, '+14', 'https://www.youtube.com/results?search_query=Michael+trailer+oficial', 'posters/michael.jpg', '2026-04-24', 'FUERA_DE_CARTELERA'),
(44, 'El Diablo Viste a la Moda 2', 'Miranda Priestly lucha por mantener su poder ante el declive de las revistas impresas.', 120, '+14', 'https://www.youtube.com/results?search_query=El+Diablo+Viste+a+la+Moda+2+trailer+oficial', 'posters/el-diablo-viste-a-la-moda-2.jpg', '2026-05-01', 'FUERA_DE_CARTELERA'),
(45, 'Toy Story 5', 'Woody, Buzz y los juguetes enfrentan su mayor desafío: la tecnología.', 100, 'APT', 'https://www.youtube.com/results?search_query=Toy+Story+5+trailer+oficial', 'posters/toy-story-5.jpg', '2026-06-19', 'FUERA_DE_CARTELERA'),
(46, 'La Odisea', 'Odiseo emprende un largo y peligroso viaje de regreso a casa tras la guerra de Troya.', 170, '+14', 'https://www.youtube.com/results?search_query=La+Odisea+trailer+oficial', 'posters/la-odisea.jpg', '2026-07-17', 'FUERA_DE_CARTELERA');

